import Fuse from "fuse.js";
import type { Course, TranscriptLine } from "./types";
import { course as defaultCourse, flattenEntries } from "./course";

// Generated by scripts/scrape-transcripts.ts (map of ytId → lines)
import bundle from "@/data/transcripts/bundle.json";

export const allTranscripts = bundle as Record<string, TranscriptLine[]>;

export type SearchResultKind = "entry" | "transcript";

export interface SearchResult {
  kind: SearchResultKind;
  slug: string;
  title: string;
  parent: string;
  clipIdx?: number; // which clip within the entry
  t?: number; // segment-relative time
  display: string;
}

interface IndexedItem {
  kind: SearchResultKind;
  slug: string;
  title: string;
  parent: string;
  clipIdx?: number;
  t?: number;
  text: string;
}

let cachedIndex: Fuse<IndexedItem> | null = null;

export function buildSearchIndex(c: Course = defaultCourse): Fuse<IndexedItem> {
  if (cachedIndex) return cachedIndex;
  const items: IndexedItem[] = [];
  for (const { part, entry } of flattenEntries(c)) {
    items.push({
      kind: "entry",
      slug: entry.slug,
      title: entry.title,
      parent: part.title,
      text: `${entry.title}\n${entry.summary}`,
    });
    entry.clips.forEach((clip, clipIdx) => {
      const lines = allTranscripts[clip.ytId];
      if (!lines) return;
      const seg = clip.end > clip.start ? lines.filter((l) => l.t >= clip.start && l.t < clip.end) : lines;
      for (const line of seg) {
        items.push({
          kind: "transcript",
          slug: entry.slug,
          title: entry.title,
          parent: part.title,
          clipIdx,
          t: line.t - clip.start,
          text: line.text,
        });
      }
    });
  }
  cachedIndex = new Fuse(items, {
    keys: ["text"],
    includeScore: true,
    includeMatches: true,
    threshold: 0.38,
    ignoreLocation: true,
    minMatchCharLength: 2,
  });
  return cachedIndex;
}

export function fmtTime(sec: number): string {
  const s = Math.max(0, Math.floor(sec));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const r = s % 60;
  const pad = (n: number) => String(n).padStart(2, "0");
  return h > 0 ? `${h}:${pad(m)}:${pad(r)}` : `${m}:${pad(r)}`;
}

export function searchResults(index: Fuse<IndexedItem>, query: string, limit = 8): SearchResult[] {
  if (!query.trim()) return [];
  return index.search(query, { limit }).map((r) => ({
    kind: r.item.kind,
    slug: r.item.slug,
    title: r.item.title,
    parent: r.item.parent,
    clipIdx: r.item.clipIdx,
    t: r.item.t,
    display: r.item.kind === "entry" ? r.item.title : r.item.text,
  }));
}
